const vulns = $input.all()[0].json.vulnerabilities || [];
const extracted = vulns.map(v => {
  const cve = v.cve.id;
  const m = v.cve.metrics?.cvssMetricV31?.[0] || v.cve.metrics?.cvssMetricV30?.[0] || v.cve.metrics?.cvssMetricV2?.[0];
  const cvss = m?.cvssData?.baseScore ?? null;
  const cvss_vector = m?.cvssData?.vectorString ?? null;
  const description = (v.cve.descriptions?.[0]?.value || '').substring(0, 500);
  const publishedDate = v.cve.published || null;
  return { cve, cvss, cvss_vector, description, publishedDate };
});
return extracted.map(item => ({ json: { item } }));

const items = $input.all().map(e => e.json.item).filter(i => i && i.cve);
if (items.length === 0) return [];

const EPSS_URL = 'https://api.first.org/data/v1/epss';
let epssMap = {};
try {
  for (let i = 0; i < items.length; i += 100) {
    const cves = items.slice(i, i + 100).map(x => x.cve);
    const resp = await $http.get(EPSS_URL + '?cve=' + encodeURIComponent(cves.join(',')), {
      timeout: 30000, headers: { 'User-Agent': 'grupo-x-thesis/2.0' }
    });
    const records = (resp && resp.data) || [];
    for (const r of records) {
      if (r && r.cve) epssMap[r.cve] = { epss: parseFloat(r.epss), percentile: parseFloat(r.percentile), date: r.date };
    }
  }
} catch (e) {}

return items.map(item => {
  const cvss = item.cvss != null ? Math.min(Math.max(parseFloat(item.cvss) || 0, 0), 10) : null;
  const ep = epssMap[item.cve];
  return { json: { item: {
    cve: item.cve, cvss, cvss_vector: item.cvss_vector || null,
    description: (item.description || '').trim(), publishedDate: item.publishedDate || null,
    epss: ep ? ep.epss : null, epss_percentile: ep ? ep.percentile : null,
    epss_date: ep ? ep.date : null, epss_source: ep ? 'first.org' : 'unavailable',
    processing_status: cvss == null ? 'error' : (ep ? 'success' : 'no_epss'),
    error_reason: cvss == null ? 'CVSS no disponible' : (ep ? null : 'CVE no encontrado en EPSS')
  }} }; });

const item = $json.item;
const txt = (item.description || '').toLowerCase();
let asset = 'Sistema General';
let crit = 5;
if (txt.includes('nginx')) { asset = 'Servidor Nginx'; crit = 10; }
else if (txt.includes('apache')) { asset = 'Servidor Apache'; crit = 8; }
else if (txt.includes('wordpress')) { asset = 'Aplicacion WordPress'; crit = 6; }
else if (txt.includes('tomcat')) { asset = 'Servidor Tomcat'; crit = 8; }
else if (txt.includes('kubernetes') || txt.includes('k8s')) { asset = 'Orquestador Kubernetes'; crit = 9; }
else if (txt.includes('docker') || txt.includes('container')) { asset = 'Plataforma Docker'; crit = 7; }
else if (txt.includes('linux')) { asset = 'Servidor Linux'; crit = 6; }
else if (txt.includes('windows')) { asset = 'Servidor Windows'; crit = 6; }
else if (txt.includes('.net') || txt.includes('asp.net')) { asset = 'Plataforma .NET'; crit = 7; }
else if (txt.includes('mysql') || txt.includes('postgresql') || txt.includes('sql server')) { asset = 'Base de Datos'; crit = 9; }
else if (txt.includes('redis')) { asset = 'Cache Redis'; crit = 5; }
return { json: { item: { ...item, correlated_asset: asset, asset_criticality: crit } } };

const item = $json.item;
let irc = null;
if (item.cvss != null && item.epss != null && item.asset_criticality != null) {
  irc = (item.cvss * 0.4) + (item.epss * 10 * 0.4) + (item.asset_criticality * 0.2);
} else if (item.cvss != null && item.asset_criticality != null) {
  irc = (item.cvss * 0.6) + (item.asset_criticality * 0.4);
}
if (irc != null) irc = parseFloat(Math.min(irc, 10).toFixed(2));
return { json: { item: { ...item, irc } } };

const item = $json.item;
if (!item) return { json: { item: null } };
let severity = 'Media';
let is_critical = false;
let alert_event = null;
if (item.irc != null) {
  if (item.irc >= 7.5) { severity = 'Crítica'; is_critical = true; alert_event = 'CRITICAL_ALERT_GENERATED'; }
  else if (item.irc >= 5.0) { severity = 'Alta'; }
  else if (item.irc >= 2.5) { severity = 'Media'; }
  else { severity = 'Baja'; }
} else {
  if (item.cvss != null && item.cvss >= 9.0) { severity = 'Crítica'; is_critical = true; alert_event = 'CRITICAL_ALERT_GENERATED'; }
  else if (item.cvss != null && item.cvss >= 7.0) { severity = 'Alta'; }
  else if (item.cvss != null && item.cvss >= 4.0) { severity = 'Media'; }
  else { severity = 'Baja'; }
}
return { json: { item: { ...item, is_critical, severity_override: severity, alert_event } } };

const item = $json.item;
if (!item) return [];
const desc = (item.description || '').toLowerCase();
const asset = (item.correlated_asset || '').toLowerCase();
let companies = [];
try {
  const resp = await $http.get('http://host.docker.internal:8000/webhook/n8n/empresas', {
    headers: { 'x-api-key': 'grp-x-n8n-secret-2025' }
  });
  companies = Array.isArray(resp) ? resp : (resp.data || []);
} catch (e) { companies = []; }

let bestCompany = null;
let bestScore = -1;
let bestTech = null;
for (const company of companies) {
  const techs = company.technologies || [];
  let score = 0;
  let matched = null;
  for (const tech of techs) {
    const tl = tech.toLowerCase();
    if (desc.includes(tl)) { score += 2; if (!matched) matched = tech; }
    if (asset.includes(tl)) { score += 1; if (!matched) matched = tech; }
  }
  if (score > bestScore) { bestScore = score; bestCompany = company; bestTech = matched; }
}
if (!bestCompany && companies.length > 0) { bestCompany = companies[0]; }

const sev = item.severity_override;
const analyst_id = (sev === 'Crítica' || sev === 'Alta') ? 2 : 3;
return { json: {
  payload: {
    cve: item.cve, description: item.description,
    affected_technology: bestTech,
    irc: item.irc, severity: sev, status: 'Pendiente',
    company_id: bestCompany ? bestCompany.id : 1,
    assigned_analyst_id: analyst_id,
    cvss: item.cvss, cvss_vector: item.cvss_vector,
    epss: item.epss, epss_date: item.epss_date,
    epss_percentile: item.epss_percentile,
    asset_criticality: item.asset_criticality,
    epss_source: item.epss_source,
    published_date: item.publishedDate,
    processing_status: item.processing_status,
    error_reason: item.error_reason
  }
} };

const item = $json.payload;
if (!item) return undefined;

let exists = false;
try {
  const resp = await $http.get(
    'http://host.docker.internal:8000/webhook/n8n/vulnerabilidades/existe?cve=' +
    encodeURIComponent(item.cve) + '&company_id=' + encodeURIComponent(item.company_id),
    { headers: { 'x-api-key': 'grp-x-n8n-secret-2025' }, timeout: 5000 }
  );
  const data = resp.data || resp;
  exists = data.exists === true;
} catch (e) {
  exists = false;
}

if (exists) return undefined;
return { json: { payload: item } };

const allResults = $input.all();
let successCount = 0;
let skippedCount = 0;
let errorCount = 0;
allResults.forEach(result => {
  if (result.json && (result.json.id || result.json.cve)) { successCount++; }
  else if (result.json && result.json.exists === true) { skippedCount++; }
  else { errorCount++; }
});
return [{ json: {
  execution_summary: {
    timestamp: new Date().toISOString(),
    total_processed: successCount + skippedCount + errorCount,
    created: successCount, skipped_duplicates: skippedCount, errors: errorCount,
    status: errorCount === 0 ? 'SUCCESS' : 'PARTIAL_SUCCESS'
  }
} }];
